(1267, 313, '_wp_attachment_metadata', 'a:6:{s:5:\"width\";i:1267;s:6:\"height\";i:930;s:4:\"file\";s:21:\"2026/05/keynote-1.jpg\";s:8:\"filesize\";i:120031;s:5:\"sizes\";a:5:{s:6:\"medium\";a:5:{s:4:\"file\";s:21:\"keynote-1-300x220.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:220;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:13405;}s:5:\"large\";a:5:{s:4:\"file\";s:22:\"keynote-1-1024x752.jpg\";s:5:\"width\";i:1024;s:6:\"height\";i:752;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:80324;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:21:\"keynote-1-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:5765;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:21:\"keynote-1-768x564.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:564;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:52221;}s:18:\"cmplz_banner_image\";a:5:{s:4:\"file\";s:21:\"keynote-1-350x100.jpg\";s:5:\"width\";i:350;s:6:\"height\";i:100;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:6650;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"1\";s:8:\"keywords\";a:0:{}}}'),
